using System.Collections.Concurrent; using PresenterConsole.Contracts;
namespace PresenterConsole.Sync;
public sealed class SyncEngine : IDisposable { readonly ConcurrentDictionary<string,byte> ids=new(); readonly Timer timer; long last; public event EventHandler<AgentCommand>? CommandAccepted; public event EventHandler? Heartbeat; public TimeSpan HeartbeatInterval=>TimeSpan.FromSeconds(1.5); public SyncEngine()=>timer=new Timer(_=>Heartbeat?.Invoke(this,EventArgs.Empty),null,HeartbeatInterval,HeartbeatInterval); public bool TryAccept(AgentCommand c){if(!ids.TryAdd(c.CommandId,0)||c.Sequence<=Interlocked.Read(ref last))return false;Interlocked.Exchange(ref last,c.Sequence);CommandAccepted?.Invoke(this,c);return true;} public void ResetForSync()=>ids.Clear(); public WireMessage CreateSyncRequest()=>new(MessageType.SyncRequest,new AgentCommand(Guid.NewGuid().ToString("N"),Interlocked.Increment(ref last),CommandType.SyncRequest)); public void Dispose()=>timer.Dispose(); }